import csv
import io

TEXT = "sku,qty\nA,3\nB,0\nC,x\nD,12\n"

def extract(text):
    return list(csv.DictReader(io.StringIO(text)))

def transform(rows):
    good, rejected = [], []
    for row in rows:
        qty = row["qty"]
        if qty.isdigit() and int(qty) > 0:
            good.append((row["sku"], int(qty)))
        else:
            rejected.append(row["sku"])
    return good, rejected

def run(source, sink):
    rows = extract(source())
    good, rejected = transform(rows)
    sink(good)
    return {"read": len(rows), "loaded": len(good), "rejected": len(rejected)}

loaded = []
print(run(lambda: TEXT, loaded.extend))
print(loaded)

